<template><div v-if="member"><button class="back-btn" @click="$emit('back')"><ChevronLeft/>Voltar para equipe</button><div class="welcome-row"><div><p class="eyebrow">ATIVIDADES DO MEMBRO</p><h1>{{member.name}}</h1><p class="subcopy">{{member.job}} · {{member.role}}</p></div></div><section class="panel member-overview"><Avatar :member="member"/><div><strong>{{member.name}}</strong><span>{{member.email}}</span></div><dl><div><dt>Status</dt><dd :class="member.blocked?'blocked-text':'active-text'">{{member.blocked?'Acesso bloqueado':'Ativo'}}</dd></div><div><dt>Tarefas</dt><dd>{{related.length}}</dd></div><div><dt>Projetos</dt><dd>{{relatedProjects}}</dd></div></dl></section><section class="panel"><div class="panel-head"><div><h2>Tarefas atribuídas</h2><p>Atividades no workspace atual</p></div></div><div class="table-wrap"><table><tbody><tr v-for="t in related" :key="t.id" @click="$emit('task',t)"><td><strong>{{t.title}}</strong></td><td>{{projects.find(p=>p.id===t.projectId)?.name}}</td><td>{{t.due}}</td><td><span :class="['status',t.status==='Concluída'?'green':t.status==='Em andamento'?'blue':'gray']">{{t.status}}</span></td></tr></tbody></table></div></section><section class="panel"><div class="panel-head"><div><h2>Alterações recentes</h2><p>Atividades persistidas no workspace</p></div></div><template v-if="activities.length"><div class="activity" v-for="item in activities.slice(0,5)" :key="item.id"><span class="avatar">{{item.actor?.profile?.name?.slice(0,1)||'?'}}</span><p><strong>{{activityLabel(item.type)}}</strong><br/><small>{{new Date(item.createdAt).toLocaleString('pt-BR')}}</small></p></div></template><p v-else class="empty">Nenhuma alteração recente.</p></section></div><div v-else class="empty">Membro não encontrado.</div></template>
<script setup lang="ts">import{computed}from"vue";import{ChevronLeft}from"lucide-vue-next";import Avatar from"./Avatar.vue";import type{Member,Project,Task}from"../stores/taskflow";import type{ActivityRecord}from"../stores/business";const props=defineProps<{member?:Member;tasks:Task[];projects:Project[];activities:ActivityRecord[]}>();defineEmits(["back","task"]);const related=computed(()=>props.tasks.filter(t=>t.assigneeId===props.member?.id)),relatedProjects=computed(()=>new Set(related.value.map(t=>t.projectId)).size),activityLabel=(type:string)=>({"TASK_CREATED":"Tarefa criada","TASK_COMPLETED":"Tarefa concluída","TASK_STATUS_CHANGED":"Status alterado","TASK_PRIORITY_CHANGED":"Prioridade alterada","TASK_DUE_CHANGED":"Prazo alterado","TASK_ASSIGNEES_CHANGED":"Responsável alterado","PROJECT_CREATED":"Projeto criado","PROJECT_UPDATED":"Projeto atualizado"}[type]||"Atividade atualizada");</script>
